    let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🔣️.json")).unwrap();let law=&fixture["executionOwner"];let bytes=law["retirementGrantBytes"].as_u64().unwrap()as usize;
